"""Keep published experimental systems separate from all 73 commercial/manual records."""
from pathlib import Path
import hashlib,json,csv
from bs4 import BeautifulSoup
ROOT=Path(__file__).resolve().parents[2]

def build(cache):
 papers=[
  ('HDPE','https://www.mdpi.com/2313-4321/8/1/2','10.3390/recycling8010002','Solvay A60-7019 / recycled rigid HDPE bottles supplied by Service Conseil Sinclair','not_specified','mass',[0,25,50,60,70,80,90,100]),
  ('PP','https://www.mdpi.com/2073-4360/17/11/1556','10.3390/polym17111556','CAPILENE R 50 / post-consumer PP from yellow-bin collection','PCR','mass',[0,25,50,75,100]),
  ('PP','https://www.mdpi.com/2073-4360/18/18/2232','10.3390/polym18182232','Moplen RP340H / post-consumer PP fishing nets','PCR','mass',[70,90]),
  ('LDPE','https://www.mdpi.com/1996-1944/14/7/1795','10.3390/ma14071795','Sumikathe 206P / study-specific recycled LDPE','not_specified',None,[]),
  ('ABS','https://www.mdpi.com/2073-4360/18/14/1716','10.3390/polym18141716','ABS/SAN systems regenerated by selective dissolution; not ordinary virgin/regrind blends','not_specified',None,[]),
  ('PA6','https://www.mdpi.com/2073-4360/15/23/4561','10.3390/polym15234561','Study-specific PA6 and PA66; keep both polymer columns separate','internal_regrind',None,[])
 ]
 sources={};experiments=[];mixes=[]
 for i,(family,url,doi,identity,origin,basis,percentages) in enumerate(papers,1):
  key=hashlib.sha256(url.encode()).hexdigest();meta=json.loads(cache.joinpath(key+'.json').read_text());soup=BeautifulSoup(cache.joinpath(key+'.body').read_bytes(),'html.parser');source_id=f'REC-{i:02}';title=soup.title.get_text(' ',strip=True)
  sources[source_id]={'title':title,'url':url,'doi':doi,'type':'peer_reviewed_experimental_article','consulted_on':'2026-10-16','sha256':meta['sha256'],'verification_status':'full_public_article_read','scope':'Exact published experimental system; not properties of the currently selected commercial grade.'}
  tables=[]
  for index,table in enumerate(soup.select('table')):
   if 'Disclaimer/Publisher' in table.get_text():continue
   rows=[]
   for tr in table.find_all('tr'):
    cells=[c.get_text(' ',strip=True) for c in tr.find_all(['td','th'],recursive=False)]
    if cells:rows.append(cells)
   if rows:tables.append({'table_index':index,'rows_original':rows,'normalization':'Original cells retained, including uncertainty and qualifiers. Do not treat all numbers as measurements or machine settings.'})
  experiments.append({'id':'experiment-'+source_id,'family':family,'source_id':source_id,'component_identity_original':identity,'recycled_origin_declared':origin,'percentage_basis':basis,'virgin_catalog_id':None,'automatic_application_allowed':False,'classification':'independent_grade_experiment','tables':tables,'limitations':['Experimental identity differs from the 64 retained commercial grades.','No interpolation to another formulation or automatic transfer of mechanical, flow, thermal or drying data.','Published machine settings are study conditions, not recommended settings for the user.']})
  for v in percentages:mixes.append({'id':f'{source_id}-V{v}-R{100-v}','experiment_id':'experiment-'+source_id,'family':family,'virgin_percent':v,'recycled_percent':100-v,'percentage_basis':basis,'source_id':source_id,'automatic_application_allowed':False,'measured_properties_scope':'Use original experimental tables; no interpolated properties assigned to this composition.'})
 families=[]
 for family in ['HDPE','LDPE','LLDPE','PP','PET','PVC','ABS','PA6','PC']:
  evidence=[e['source_id'] for e in experiments if e['family']==family]
  families.append({'family':family,'evaluation':'requires_case_validation','permitted_analysis_origins':['PIR','PCR','internal_regrind','commercial_recycled'],'experimental_source_ids':evidence,'numeric_properties_inherited':False,'compatibility':'unknown_for_a_new_formulation','percentage_recommendation':None,'study_status':'Specific public experimental evidence read' if evidence else 'Family reviewed; no directly applicable experimental values reconfirmed in the consulted accessible sources.','required_case_information':['component identity and source','declared polymer family and formulation','origin PIR/PCR/internal/commercial','processing history and cycles','humidity and pretreatment','contamination and compatibility','application requirements'],'limitations':['No universal recycled percentage or industrial suitability is established.','Food-contact, medical and structural status require case-specific evidence.']})
 out={'schema':'ccip-recycling-evidence/1','revision':'1.0.0','sources':sources,'families':families,'experiments':experiments,'experimental_formulations':mixes,'percentage_presets':[[100-i*10,i*10] for i in range(11)],'preset_basis':'mass','preset_convention':'first virgin / second recycled','model_policy':{'density':'ideal additive specific volumes only with matching documented conditions and explicit acceptance','mfr_mvr':'unavailable without a model validated for exact components','mechanical_thermal_drying':'no universal averaging or virgin inheritance'}}
 (ROOT/'src/data/recycling.v1.json').write_text(json.dumps(out,ensure_ascii=False,separators=(',',':'))+'\n')
 (ROOT/'docs/etapa-3/recycling-families.json').write_text(json.dumps(families,ensure_ascii=False,indent=2)+'\n');(ROOT/'docs/etapa-3/experimental-formulations.json').write_text(json.dumps(mixes,ensure_ascii=False,indent=2)+'\n')
 with (ROOT/'docs/etapa-3/recycling-families.csv').open('w',newline='') as f:
  w=csv.writer(f);w.writerow(['family','evaluation','experimental_source_ids','compatibility','numeric_properties_inherited','percentage_recommendation'])
  for r in families:w.writerow([r['family'],r['evaluation'],';'.join(r['experimental_source_ids']),r['compatibility'],False,None])
 with (ROOT/'docs/etapa-3/experimental-formulations.csv').open('w',newline='') as f:
  w=csv.writer(f);w.writerow(['id','family','virgin_percent','recycled_percent','percentage_basis','source_id','automatic_application_allowed'])
  for r in mixes:w.writerow([r[k] for k in ['id','family','virgin_percent','recycled_percent','percentage_basis','source_id','automatic_application_allowed']])
 print(len(families),'families;',len(experiments),'separate experimental systems;',len(mixes),'documented compositions')
if __name__=='__main__':
 import argparse
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--cache',type=Path,required=True);build(p.parse_args().cache)
